-- Codes from coupon sites are 'web' (shown as Unverified until shoppers confirm them);
-- offers published by the brand itself are 'brand'. Fingerprints match lib/coupons/refresh.ts,
-- so the automatic refresh updates these rows instead of duplicating them. Safe to re-run.
insert into public.coupon_offers (brand_id, kind, code, title, discount_text, min_spend, conditions, new_users_only, works_in_nigeria, source_url, source_type, expires_at, fingerprint, last_verified_at)
